{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h2",
        "intro_text",
        "material_composition_header_stack",
        "material_composition_text",
        "material_composition_bullet_points_stack",
        "care_h2",
        "care_intro_text",
        "care_instructions_stack",
        "outdoor_performance_header_stack",
        "outdoor_performance_bullet_points_stack",
        "quick_actions_h3",
        "quick_actions_stack",
        "sources_h3",
        "sources_stack"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Merino Wool Sweater Essentials",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "A men's 100% merino wool sweater is crafted entirely from the exceptionally fine fibers of merino sheep, known for their superior softness, breathability, and temperature-regulating properties. This essential garment offers unparalleled comfort and versatility for various climates and occasions.",
        "variant": "body"
      },
      "children": []
    },
    "material_composition_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md"
      },
      "children": [
        "material_composition_header_text"
      ]
    },
    "material_composition_header_text": {
      "type": "Text",
      "props": {
        "text": "Material Composition",
        "variant": "h3"
      },
      "children": []
    },
    "material_composition_text": {
      "type": "Text",
      "props": {
        "text": "Made from 100% pure merino wool, this sweater provides natural elasticity, odor resistance, and moisture-wicking capabilities.",
        "variant": "body"
      },
      "children": []
    },
    "material_composition_bullet_points_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "material_composition_bp1",
        "material_composition_bp2",
        "material_composition_bp3",
        "material_composition_bp4"
      ]
    },
    "material_composition_bp1": {
      "type": "Text",
      "props": {
        "text": "• Ultra-fine 18.5 micron merino fibers",
        "variant": "body"
      },
      "children": []
    },
    "material_composition_bp2": {
      "type": "Text",
      "props": {
        "text": "• Naturally breathable and moisture-wicking",
        "variant": "body"
      },
      "children": []
    },
    "material_composition_bp3": {
      "type": "Text",
      "props": {
        "text": "• Odor-resistant for extended wear",
        "variant": "body"
      },
      "children": []
    },
    "material_composition_bp4": {
      "type": "Text",
      "props": {
        "text": "• Soft, non-itchy feel against the skin",
        "variant": "body"
      },
      "children": []
    },
    "care_h2": {
      "type": "Text",
      "props": {
        "text": "Care Instructions",
        "variant": "h2"
      },
      "children": []
    },
    "care_intro_text": {
      "type": "Text",
      "props": {
        "text": "To maintain the quality and longevity of your merino wool sweater, please follow these guidelines:",
        "variant": "body"
      },
      "children": []
    },
    "care_instructions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "care_instruction_1",
        "care_instruction_2",
        "care_instruction_3",
        "care_instruction_4"
      ]
    },
    "care_instruction_1": {
      "type": "Text",
      "props": {
        "text": "• Hand wash cold or machine wash on wool cycle with mild detergent.",
        "variant": "body"
      },
      "children": []
    },
    "care_instruction_2": {
      "type": "Text",
      "props": {
        "text": "• Lay flat to dry; do not tumble dry.",
        "variant": "body"
      },
      "children": []
    },
    "care_instruction_3": {
      "type": "Text",
      "props": {
        "text": "• Do not bleach or iron at high temperatures.",
        "variant": "body"
      },
      "children": []
    },
    "care_instruction_4": {
      "type": "Text",
      "props": {
        "text": "• Store folded to prevent stretching.",
        "variant": "body"
      },
      "children": []
    },
    "outdoor_performance_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md"
      },
      "children": [
        "outdoor_performance_header_text"
      ]
    },
    "outdoor_performance_header_text": {
      "type": "Text",
      "props": {
        "text": "Outdoor Performance",
        "variant": "h3"
      },
      "children": []
    },
    "outdoor_performance_bullet_points_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "outdoor_performance_bp1",
        "outdoor_performance_bp2",
        "outdoor_performance_bp3",
        "outdoor_performance_bp4"
      ]
    },
    "outdoor_performance_bp1": {
      "type": "Text",
      "props": {
        "text": "• Excellent thermal regulation in varying temperatures",
        "variant": "body"
      },
      "children": []
    },
    "outdoor_performance_bp2": {
      "type": "Text",
      "props": {
        "text": "• Lightweight and packable for travel",
        "variant": "body"
      },
      "children": []
    },
    "outdoor_performance_bp3": {
      "type": "Text",
      "props": {
        "text": "• Quick-drying properties for active use",
        "variant": "body"
      },
      "children": []
    },
    "outdoor_performance_bp4": {
      "type": "Text",
      "props": {
        "text": "• Natural UV protection",
        "variant": "body"
      },
      "children": []
    },
    "quick_actions_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "shop_sweaters_button",
        "contact_support_button"
      ]
    },
    "shop_sweaters_button": {
      "type": "Button",
      "props": {
        "label": "Shop All Sweaters"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/shop/sweaters"
          }
        }
      },
      "children": []
    },
    "contact_support_button": {
      "type": "Button",
      "props": {
        "label": "Contact Support"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/support"
          }
        }
      },
      "children": []
    },
    "sources_h3": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "merino_benefits_button",
        "wool_care_guide_button"
      ]
    },
    "merino_benefits_button": {
      "type": "Button",
      "props": {
        "label": "Merino Wool Benefits"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.merinowool.com/benefits"
          }
        }
      },
      "children": []
    },
    "wool_care_guide_button": {
      "type": "Button",
      "props": {
        "label": "Wool Care Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.woolmark.com/care"
          }
        }
      },
      "children": []
    }
  }
}
